BootCopy:
; Copy 005F bytes into RAM at 8000 then transfer control
    LD HL,0xF80E
    LD DE,0x8000
    LD BC,0x005F
    LDIR
    JP BootRam
DEPHASE
PHASE 0x8000
BootRam:
    LD SP,0x8000
    LD A,0x0F
    OUT (ROM_CONFIG),A
    CALL RomBiosTable
    XOR A
    OUT (DRIVE_LATCH),A
    LD A,0x10
    OUT (DRIVE_LATCH),A
    LD BC,0x0303
    LD HL,0x8033
    CALL L_803C
    LD BC,0x804C
    CALL L_E012
    LD HL,0x8057
    LD (HL),0x01
L_8025:
    LD BC,0x804C
    CALL L_E012
    JR C,L_8025
    LD A,(0x804E)
    JP L_3000
    DB 0xDF,0xFF ; unreached
L_8035:
    OUT (FDC_DATA),A
    EX (SP),HL
    EX (SP),HL
    EX (SP),HL
    EX (SP),HL
    RET
L_803C:
    IN A,(FDC_MSR)
    RLA
    JR NC,L_803C
    RLA
    RET C
    LD A,C
    CALL L_8035
    LD C,(HL)
    INC HL
    DJNZ L_803C
    RET
    DB 0x01,0x00,0x00,0x00,0x00,0x00,0x30,0x00 ; unreached
    DB 0x00,0x00,0x00,0x10,0x00,0x00,0x00,0x00 ; unreached
    DB 0x00,0x00,0x00 ; unreached
DEPHASE
PHASE 0xF86D
